const R={'0':{codigo:0,estados:['RS'],descricao:'Rio Grande do Sul'},'1':{codigo:1,estados:['DF','GO','MS','MT','TO'],descricao:'Distrito Federal, Goiás, Mato Grosso do Sul, Mato Grosso e Tocantins'},'2':{codigo:2,estados:['AC','AM','AP','PA','RO','RR'],descricao:'Acre, Amazonas, Amapá, Pará, Rondônia e Roraima'},'3':{codigo:3,estados:['CE','MA','PI'],descricao:'Ceará, Maranhão e Piauí'},'4':{codigo:4,estados:['AL','PB','PE','RN'],descricao:'Alagoas, Paraíba, Pernambuco e Rio Grande do Norte'},'5':{codigo:5,estados:['BA','SE'],descricao:'Bahia e Sergipe'},'6':{codigo:6,estados:['MG'],descricao:'Minas Gerais'},'7':{codigo:7,estados:['ES','RJ'],descricao:'Espírito Santo e Rio de Janeiro'},'8':{codigo:8,estados:['SP'],descricao:'São Paulo'},'9':{codigo:9,estados:['PR','SC'],descricao:'Paraná e Santa Catarina'}};const B=new Set(['00000000000','11111111111','22222222222','33333333333','44444444444','55555555555','66666666666','77777777777','88888888888','99999999999']);export class CpfValidatorPro{constructor(o={}){this.endpoint=o.endpoint||'https://cpfvalidator-pro-api.fichatecnica-api.workers.dev';this.apiKey=o.apiKey||'';}static limpar(c){return c?String(c).replace(/\D/g,''):'';}static formatar(c){const l=CpfValidatorPro.limpar(c);if(l.length!==11)return c;return`${l.slice(0,3)}.${l.slice(3,6)}.${l.slice(6,9)}-${l.slice(9,11)}`;}static validarLocal(i){if(i===null||i===undefined)return{valido:false,motivo:'CPF não informado'};const s=String(i).trim();const l=s.replace(/\D/g,'');if(!l)return{valido:false,cpfInformado:s,motivo:'Não contém números'};if(l.length!==11)return{valido:false,cpfInformado:s,cpfLimpo:l,motivo:`Quantidade de dígitos inválida: esperado 11, recebido ${l.length}`};if(B.has(l))return{valido:false,cpfInformado:s,cpfLimpo:l,motivo:'Dígitos idênticos repetidos são matematicamente inválidos'};let s1=0;for(let j=0;j<9;j++)s1+=parseInt(l.charAt(j),10)*(10-j);let r1=s1%11;let d1=r1<2?0:11-r1;if(d1!==parseInt(l.charAt(9),10))return{valido:false,cpfInformado:s,cpfLimpo:l,digitoVerificadorEsperado:`${d1}?`,motivo:'Primeiro dígito verificador incorreto'};let s2=0;for(let j=0;j<10;j++)s2+=parseInt(l.charAt(j),10)*(11-j);let r2=s2%11;let d2=r2<2?0:11-r2;if(d2!==parseInt(l.charAt(10),10))return{valido:false,cpfInformado:s,cpfLimpo:l,digitoVerificadorEsperado:`${d1}${d2}`,motivo:'Segundo dígito verificador incorreto'};const r=R[l.charAt(8)]||{codigo:null,estados:[],descricao:'Desconhecida'};return{valido:true,cpf:CpfValidatorPro.formatar(l),cpfLimpo:l,digitosVerificadores:`${d1}${d2}`,regiaoFiscal:r,tipo:'Pessoa Física (Brasil)',algoritmo:'Módulo 11 (RFC Receita Federal)'};}async validar(c){const l=CpfValidatorPro.limpar(c);const u=`${this.endpoint.replace(/\/$/,'')}/api/validar-cpf?cpf=${encodeURIComponent(l)}`;const h={'Accept':'application/json'};if(this.apiKey)h['Authorization']=`Bearer ${this.apiKey}`;const res=await fetch(u,{headers:h});return await res.json();}static gerarTeste(u=null){const n=[];for(let i=0;i<8;i++)n.push(Math.floor(Math.random()*10));const rg=(u!==null&&u>=0&&u<=9)?Number(u):Math.floor(Math.random()*10);n.push(rg);let s1=0;for(let i=0;i<9;i++)s1+=n[i]*(10-i);let r1=s1%11;let d1=r1<2?0:11-r1;n.push(d1);let s2=0;for(let i=0;i<10;i++)s2+=n[i]*(11-i);let r2=s2%11;let d2=r2<2?0:11-r2;n.push(d2);return CpfValidatorPro.formatar(n.join(''));}}export default CpfValidatorPro;
